mapper.select:
SELECT

FROM ccds_duty_day
WHERE station_id = #{stationId}
  AND duty_date = #{dutyDate}

SELECT

FROM ccds_duty_day
WHERE station_id = #{stationId}
  AND duty_date BETWEEN #{startDate} AND #{endDate}
ORDER BY duty_date ASC

SELECT d.id, d.station_id, d.duty_date, d.main_officer_id, d.deputy_officer_id, d.note, d.group_snapshot_json, d.vehicle_snapshot_json, d.gmt_create, d.gmt_modified FROM ccds_duty_day d INNER JOIN ( SELECT station_id, MAX(duty_date) AS max_date FROM ccds_duty_day WHERE station_id IN
#{item}
GROUP BY station_id ) latest ON latest.station_id = d.station_id AND latest.max_date = d.duty_date ORDER BY d.station_id ASC
